if(!Array.isArray(read(K.A,null))){const data=[["Jett Lawrence","18","450","Team Honda HRC","Honda"],["Hunter Lawrence","96","450","Team Honda HRC","Honda"],["Chase Sexton","4","450","Red Bull KTM Factory Racing","KTM"],["Eli Tomac","3","450","Yamaha Star Racing","Yamaha"],["Haiden Deegan","38","250","Yamaha Star Racing","Yamaha"],["Jo Shimoda","30","250","Honda HRC","Honda"],["Levi Kitchen","47","250","Pro Circuit Kawasaki","Kawasaki"],["Tim Gajser","243","MXGP","Team HRC","Honda"],["Jorge Prado","61","MXGP","Red Bull KTM","KTM"],["Kay de Wolf","74","MX2","Husqvarna Factory Racing","Husqvarna"],["Simon Längenfelder","516","MX2","Red Bull KTM","KTM"],["Marc Márquez","93","MotoGP","Ducati Lenovo","Ducati"],["Francesco Bagnaia","63","MotoGP","Ducati Lenovo","Ducati"],["Fabio Quartararo","20","MotoGP","Yamaha MotoGP","Yamaha"],["Max Verstappen","1","F1","Red Bull Racing","Red Bull Racing"],["Lando Norris","4","F1","McLaren","McLaren"],["Charles Leclerc","16","F1","Ferrari","Ferrari"],["Oscar Piastri","81","F1","McLaren","McLaren"],["Lewis Hamilton","44","F1","Ferrari","Ferrari"]];saveAthletes(data.map(([name,number,c,raceTeam,manufacturer])=>({id:uid(),name,number:String(number).trim(),class:c,raceTeam,manufacturer,pointsLeader:false,reigningSMXChampion:false,reigningWorldChampion:false})))}
// Normalize racing numbers as strings (never parseInt, so numbers such as 01 stay intact).
const storedAthletes=athletes().map(a=>({...a,number:normalizeNumber(a.number,name(a)),nationality:normalizeNationality(a.nationality)||KNOWN_NATIONALITY[norm(name(a))]||""}));
if(JSON.stringify(storedAthletes)!==JSON.stringify(athletes()))saveAthletes(storedAthletes);
