function renderTrades(k){const list=read(K.TR,[]).filter(t=>t.fromKey===k||t.toKey===k).slice().reverse();$("tradeList").innerHTML=table(["Status","From","To","Offer","Request","Message","Action"],list.map(t=>`<tr><td>${esc(t.status)}</td><td>${esc(t.fromName)}</td><td>${esc(t.toName)}</td><td>${tradeNamesHTML(t,"offer")}</td><td>${tradeNamesHTML(t,"request")}</td><td>${esc(t.note)}</td><td>${t.toKey===k&&t.status==="Pending"?`<button class="inline" data-accept="${t.id}">Accept</button> <button class="inline" data-reject="${t.id}">Reject</button>`:"—"}</td></tr>`));$("tradeList").querySelectorAll("[data-accept]").forEach(b=>b.onclick=()=>respondTrade(b.dataset.accept,"Accepted",k));$("tradeList").querySelectorAll("[data-reject]").forEach(b=>b.onclick=()=>respondTrade(b.dataset.reject,"Rejected",k))}
function respondTrade(tid,status,k){if(renderRosterLockNotice("trades"))return;const all=read(K.TR,[]),tr=all.find(t=>t.id===tid);if(!tr||tr.toKey!==k||tr.status!=="Pending")return;if(status==="Accepted"){const a=teams().find(t=>key(t)===tr.fromKey),b=teams().find(t=>key(t)===tr.toKey);const offered=tr.offerIds.map(i=>roster(a).find(r=>id(r)===i)),requested=tr.requestIds.map(i=>roster(b).find(r=>id(r)===i));if(offered.some(x=>!x)||requested.some(x=>!x)){alert("Trade could not be completed: a roster changed.");return}const ar=roster(a).filter(r=>!tr.offerIds.includes(id(r))).concat(requested),br=roster(b).filter(r=>!tr.requestIds.includes(id(r))).concat(offered);const valid=r=>r.length<=22&&Object.entries(REQ).every(([c,n])=>r.filter(x=>cls(x)===c).length<=n);if(!valid(ar)||!valid(br)){alert("Trade exceeds a roster quota.");return}a.roster=ar;b.roster=br;saveTeams(teams().map(t=>key(t)===key(a)?a:key(t)===key(b)?b:t))}tr.status=status;write(K.TR,all);showTrades(k);refresh()}
function draftInit(){const room=$("draftRoom");room.onchange=renderDraft; $("draftForm").onsubmit=e=>{e.preventDefault();const t=teams().find(t=>key(t)===$("draftTeam").value),a=athletes().find(a=>id(a)===$("draftAthlete").value),r=room.value;if(!t||!a||owner(a)){$("draftMessage").textContent="Choose a team and free agent.";return}if(roster(t).length>=22||counts(t)[cls(a)]>=REQ[cls(a)]){$("draftMessage").textContent="No roster spot available for this series.";return}t.roster.push({...a});saveTeams(teams().map(x=>key(x)===key(t)?t:x));const d=read(K.D,{picks:[]});d.picks.push({id:uid(),room:r,number:d.picks.filter(p=>p.room===r).length+1,athleteId:id(a),athleteName:name(a),athleteClass:cls(a),riderNumber:clean(a.number),nationality:normalizeNationality(a.nationality),teamName:tname(t),time:new Date().toISOString()});write(K.D,d);$("draftMessage").textContent="Draft pick saved.";renderDraft();refresh()};renderDraft()}
function renderDraft(){if(!$("draftStatusCard"))return;const r=$("draftRoom").value,settings=read(K.DS,{})[r]||{status:"Not started"}; $("draftStatusCard").innerHTML=`<div class="summary"><div><strong>${esc(r)}</strong><span>Draft room</span></div><div><strong>${esc(settings.status)}</strong><span>Status</span></div><div><strong>${settings.start?new Date(settings.start).toLocaleString():"Not scheduled"}</strong><span>Start time</span></div></div><p class=muted>Manual draft pick flow. Draft status is informational in this local prototype.</p>`;options($("draftTeam"),teams().map(t=>({value:key(t),label:tname(t)})),"Choose team");const free=sortRiders(athletes().filter(a=>!owner(a)&&((r==="SMX"&&["250","450"].includes(cls(a)))||(r==="MXGP"&&["MXGP","MX2"].includes(cls(a)))||r===cls(a))));options($("draftAthlete"),free.map(a=>({value:id(a),label:`${flagEmoji(a.nationality)} #${clean(a.number)||"—"} ${name(a)} — ${cls(a)}`})),"Choose available athlete");$("draftPicks").innerHTML=table(["Pick","Athlete","Series","Team","Time"],read(K.D,{picks:[]}).picks.filter(p=>p.room===r).slice().sort(comparePicksByRiderNumber).map(p=>`<tr><td>${p.number}</td><td>${flagByRider(p.athleteId,p.athleteName,p.athleteClass,p.nationality)} ${numberHTML(riderFromPick(p).number,riderFromPick(p).manufacturer,riderFromPick(p))} ${esc(p.athleteName)}</td><td>${esc(p.athleteClass)}</td><td>${esc(p.teamName)}</td><td>${new Date(p.time).toLocaleString()}</td></tr>`))}
